const lastMessage = state.messages[state.messages.length - 1];
const userTask = typeof lastMessage.content === 'string' ? lastMessage.content : JSON.stringify(lastMessage.content);

// Step 1: Classify task into a single domain
classificationPrompt = `Classify the following task into exactly ONE domain from: research, coding, writing, analysis, general.
Respond with ONLY the domain name, nothing else.

Task: ${userTask}`;

const classificationResponse = await model.invoke([{ role: 'user', content: classificationPrompt }]);
const classificationContent = typeof classificationResponse.content === 'string' ? classificationResponse.content : JSON.stringify(classificationResponse.content);
const domain = classificationContent.trim().toLowerCase();

// Step 2: Generate worker plans with domain context
const planPrompt = `You are an expert in task decomposition.
Define the team of specialists needed to accomplish the following task.

Task: ${userTask}
Domain: ${domain}

Return only the following JSON array (no explanation needed):
[
  {"name": "snake_case_role_name", "role": "description of the role", "task": "specific assigned task"},
  ...
]

Constraints:
- Define between 1 and 5 workers, only as many as needed for the task
- If one person can complete the task alone, assign only one worker
- name must be in snake_case English`;

const response = await model.invoke([{ role: 'user', content: planPrompt }]);
const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);

let workerPlans;
try {
  const jsonMatch = content.match(/\[.*\]/s);
  const parsed = jsonMatch ? JSON.parse(jsonMatch[0]) : [];
  // Enrich each worker plan with domain and relevant skills
  const domainSkillsMap = {
    research: 'arxiv-search, langgraph-docs',
    coding: 'langgraph-docs',
    writing: '',
    analysis: 'arxiv-search',
    general: 'arxiv-search, langgraph-docs, env-bootstrap, harness-bootstrap, teams'
  };
  const skills = domainSkillsMap[domain] || '';
  workerPlans = parsed.map(p => ({ ...p, domain, relevantSkills: skills }));
} catch (e) {
  console.error('[planner] Failed to parse worker plans:', e);
  workerPlans = [{ name: 'general_worker', role: 'General handler', task: userTask, domain, relevantSkills: '' }];
}

// Step 3: Generate dynamic SKILL.md for each worker
const path = require('path');
const skillsDir = 'skills/dynamic';
for (const plan of workerPlans) {
  const skillPath = path.join(skillsDir, plan.name);
  const skillMd = `---
name: ${plan.name}
description: ${plan.role}
---

# ${plan.role} Skill

## Assigned Task
${plan.task}

## Instructions
1. Read this SKILL.md file to understand your assigned task
2. Execute the task as specified
3. Report your results clearly
`;
  await write_file(`${skillPath}/SKILL.md`, skillMd);
  console.log(`[planner] Generated SKILL.md: ${skillPath}/SKILL.md`);

  if (skillsManager) {
    skillsManager.registerSkill({
      name: plan.name,
      description: plan.role,
      path: `${skillPath}/SKILL.md`,
      instructions: skillMd,
    });
  }
}

console.log(`[planner] Defined ${workerPlans.length} workers for domain: ${domain}:`, JSON.stringify(workerPlans, null, 2));
return { workerPlans, messages: [response] };

const plan = state.currentPlan;
if (!plan) {
  console.error('[worker] No currentPlan in state');
  return { workerResults: [{ name: 'unknown', result: 'Error: no plan assigned' }] };
}

console.log(`[worker:${plan.name}] Starting task: ${plan.task}`);

const cwd = '/Users/akirakudo/Desktop/MyWork/test';
const domainHint = plan.domain ? `

Task domain: ${plan.domain}` : '';
const skillsHint = plan.relevantSkills ? `
Relevant skills for this domain: ${plan.relevantSkills}` : '';
// Read dynamic SKILL.md if available
let skillContext = '';
try {
  const skillContent = await read_file('skills/dynamic/' + plan.name + '/SKILL.md');
  if (skillContent && typeof skillContent === 'string' && skillContent.trim().length > 0) {
    skillContext = '\n\n【Dynamic Skill Instructions】\n' + skillContent;
  }
} catch (e) {
  console.log(`[worker:${plan.name}] No dynamic SKILL.md found — using default instructions`);
}

const workerPrompt = `You are an expert in ${plan.role}.${domainHint}${skillsHint}${skillContext}

Assigned task: ${plan.task}

Working directory: ${cwd}
Always specify file paths as absolute paths (e.g., ${cwd}/src/formatDateJP.ts).
If you need to create or edit files or run commands, use the available tools (write_file, edit_file, bash_command, etc.) to actually execute them.
When running commands with bash_command, first cd ${cwd}.

Important constraints:
- Never use glob_files. File exploration is not needed.
- Use write_file or edit_file directly on the paths specified in the task.
- Focus only on the relevant skills listed above. Do not use unrelated skills.

Once all work is complete, report what you did in English.`;

const messages = [{ role: 'user', content: workerPrompt }];
let finalResult = '';

for (let i = 0; i < 10; i++) {
  const response = await model.invoke(messages);
  messages.push(response);

  const toolCalls = response.tool_calls || [];
  if (toolCalls.length === 0) {
    const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);
    if (content && content.trim()) {
      finalResult = content;
    }
    break;
  }

  for (const toolCall of toolCalls) {
    console.log(`[worker:${plan.name}] Calling tool: ${toolCall.name}`);
    const tool = tools.find(t => t.name === toolCall.name);
    if (!tool) {
      console.error(`[worker:${plan.name}] Tool not found: ${toolCall.name}`);
      messages.push({ role: 'tool', tool_call_id: toolCall.id, content: `Error: tool ${toolCall.name} not found` });
      continue;
    }
    const toolResult = await tool.invoke(toolCall.args);
    const toolContent = typeof toolResult === 'string' ? toolResult : JSON.stringify(toolResult);
    messages.push(new ToolMessage({ tool_call_id: toolCall.id, content: toolContent }));
  }
}

console.log(`[worker:${plan.name}] Completed. Result preview: ${finalResult.slice(0, 100)}`);
return { workerResults: [{ name: plan.name, result: finalResult }], messages: [messages[messages.length - 1]] };

console.log(`[aggregator] Aggregating ${state.workerResults.length} worker results`);

const resultsSummary = state.workerResults.map(r => `## ${r.name}\n${r.result}`).join('\n\n');

const aggregatePrompt = `The following are the research and work results from each specialist team.

${resultsSummary}

Integrate these results to create a comprehensive final report in English.
Combine the contributions of each team member appropriately and organize the response to address the user's original request.`;

let finalReport = '';
for (let attempt = 0; attempt < 3; attempt++) {
  const response = await model.invoke([{ role: 'user', content: aggregatePrompt }]);
  const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);
  if (content && content.trim()) {
    finalReport = content;
    break;
  }
  console.warn(`[aggregator] Empty response on attempt ${attempt + 1}, retrying...`);
}

if (!finalReport) {
  console.warn('[aggregator] All attempts returned empty, falling back to worker results summary');
  finalReport = state.workerResults.map(r => `## ${r.name}\n${r.result || '(no result)'}`).join('\n\n');
}

console.log('[aggregator] Final report generated, length:', finalReport.length);
return { finalReport, messages: [{ role: 'assistant', content: finalReport }] };

console.log('[finalize] Teams workflow complete');
const report = (state.finalReport && state.finalReport.trim()) ? state.finalReport : (state.messages.slice().reverse().find(m => m.role === 'assistant' && m.content && m.content.trim())?.content) || 'No report generated';
return { messages: [{ role: 'assistant', content: report }] };

console.log('[reflect] Starting workflow reflection');

// Quick exit: nothing to reflect on
if (!state.workerPlans || state.workerPlans.length === 0) {
  console.log('[reflect] No worker plans — skipping');
  return { messages: [{ role: 'assistant', content: '' }] };
}

if (!state.workerResults || state.workerResults.length === 0) {
  console.log('[reflect] No worker results — skipping');
  return { messages: [{ role: 'assistant', content: '' }] };
}

// Build reflection context
const plansSummary = state.workerPlans.map(p => `- ${p.name} (${p.role}): ${p.task}`).join('\n');
const resultsSummary = state.workerResults.map(r => `## ${r.name}\n${r.result || '(empty)'}`).join('\n\n');

const reflectionPrompt = `You are a workflow reflection analyst. Your job is to learn from completed team executions to improve future SKILL.md files.

【Worker Plans】
${plansSummary}

【Worker Results】
${resultsSummary}

【Analysis】
1. Were the worker roles appropriate for the tasks?
2. Were there any failures, retries, or suboptimal decisions?
3. Is there a reusable pattern worth recording?

【Rules】
- Only update if you found a concrete, actionable lesson
- Never modify existing content — append only
- Append to the "## Learned Patterns" section of skills/teams/SKILL.md
- If no actionable lesson, respond with an empty string and do NOT call any tools

If there is something to learn:
1. First call edit_file on "skills/teams/SKILL.md"
2. Append a new bullet under "## Learned Patterns" (create the section if it does not exist)
3. Format: "### <date> — <pattern name>\n<description of what happened and what to do differently next time>"
4. Return the updated file content

If nothing worth learning, return an empty string with no tool calls.`;

const response = await model.invoke([{ role: 'user', content: reflectionPrompt }]);
const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);

// If the model returned tool calls, let them execute (edit_file)
if (response.tool_calls && response.tool_calls.length > 0) {
  console.log(`[reflect] Model made ${response.tool_calls.length} tool call(s)`);
  const messages = [{ role: 'user', content: reflectionPrompt }];
  messages.push(response);

  for (let i = 0; i < 3; i++) {
    const toolCalls = messages[messages.length - 1].tool_calls || [];
    if (toolCalls.length === 0) break;

    for (const toolCall of toolCalls) {
      console.log(`[reflect] Executing tool: ${toolCall.name}`);
      const tool = tools.find(t => t.name === toolCall.name);
      if (!tool) {
        console.error(`[reflect] Tool not found: ${toolCall.name}`);
        messages.push({ role: 'tool', tool_call_id: toolCall.id, content: `Error: tool ${toolCall.name} not found` });
        continue;
      }
      const toolResult = await tool.invoke(toolCall.args);
      const toolContent = typeof toolResult === 'string' ? toolResult : JSON.stringify(toolResult);
      messages.push(new ToolMessage({ tool_call_id: toolCall.id, content: toolContent }));
    }

    const nextResponse = await model.invoke(messages);
    messages.push(nextResponse);
  }

  const lastMsg = messages[messages.length - 1];
  const finalContent = typeof lastMsg.content === 'string' ? lastMsg.content : JSON.stringify(lastMsg.content);
  console.log(`[reflect] Reflection complete. Output: ${String(finalContent).slice(0, 200)}`);
  return { messages: [lastMsg] };
}

console.log('[reflect] No actionable patterns found — skipping update');
return { messages: [{ role: 'assistant', content: '' }] };
